Here is the commit message:
RDMA/efa: Handle mmap insertions overflow

When inserting a new mmap entry to the xarray we should check for
'mmap_page' overflow as it is limited to 32 bits.

Fixes: 40909f664d27 ("RDMA/efa: Add EFA verbs implementation")
Signed-off-by: Gal Pressman <galpress@amazon.com>
Signed-off-by: Doug Ledford <dledford@redhat.com>

Here is the root cause:
The bug arises from the potential overflow of the `mmap_page` variable, which is limited to 32 bits. When inserting a new mmap entry, if the total number of pages exceeds this limit, it can lead to incorrect memory management and undefined behavior. The original code did not check for this overflow, making it susceptible to errors when handling large memory mappings.

Here is the patch:
  */
 static u64 mmap_entry_insert(struct efa_dev *dev, struct efa_ucontext *ucontext,
 			     void *obj, u64 address, u64 length, u8 mmap_flag)
 {
 	struct efa_mmap_entry *entry;
+	u32 next_mmap_page;
 	int err;

 	entry = kmalloc(sizeof(*entry), GFP_KERNEL);
 	if (!entry)
 		return EFA_MMAP_INVALID;

 	entry->obj = obj;
 	entry->address = address;
 	entry->length = length;
 	entry->mmap_flag = mmap_flag;

 	xa_lock(&ucontext->mmap_xa);
+	if (check_add_overflow(ucontext->mmap_xa_page,
+			       (u32)(length >> PAGE_SHIFT),
+			       &next_mmap_page))
+		goto err_unlock;
+
 	entry->mmap_page = ucontext->mmap_xa_page;
-	ucontext->mmap_xa_page += DIV_ROUND_UP(length, PAGE_SIZE);
+	ucontext->mmap_xa_page = next_mmap_page;
 	err = __xa_insert(&ucontext->mmap_xa, entry->mmap_page, entry,
 			  GFP_KERNEL);
+	if (err)
+		goto err_unlock;
+
 	xa_unlock(&ucontext->mmap_xa);
-	if (err){
-		kfree(entry);
-		return EFA_MMAP_INVALID;
-	}

 	ibdev_dbg(
 		&dev->ibdev,
 		"mmap: obj[0x%p] addr[%#llx], len[%#llx], key[%#llx] inserted\n",
 		entry->obj, entry->address, entry->length, get_mmap_key(entry));

 	return get_mmap_key(entry);
+
+err_unlock:
+	xa_unlock(&ucontext->mmap_xa);
+	kfree(entry);
+	return EFA_MMAP_INVALID;
+
 }



